const (
	// NullTag is the tag of the null value.
	NullTag = "!!null"
	// BoolTag is the tag of true and false.
	BoolTag = "!!bool"
	// IntTag is the tag of integers.
	IntTag = "!!int"
	// FloatTag is the tag of floating-point numbers.
	FloatTag = "!!float"
	// StringTag is the tag of strings.
	StringTag = "!!str"
	// SequenceTag is the tag of sequences.
	SequenceTag = "!!seq"
	// MappingTag is the tag of mappings.
	MappingTag = "!!map"
	// BinaryTag is the tag of base64-encoded binary data.
	BinaryTag = "!!binary"
	// TimestampTag is the tag of timestamps.
	TimestampTag = "!!timestamp"
	// MergeTag is the tag of the merge key ("<<").
	MergeTag = "!!merge"
)

vars.signature:
var (
	// ErrSyntax indicates the input was not well-formed YAML. Syntax errors are
	// reported as *SyntaxError values carrying a line and column.
	ErrSyntax = errors.New("yaml: syntax error")

	// ErrUnknownAnchor indicates an alias (*name) referred to an anchor that has
	// not been defined earlier in the same document.
	ErrUnknownAnchor = errors.New("yaml: unknown anchor")

	// ErrAliasBomb indicates that expanding aliases would produce more nodes
	// than the decoder is willing to materialize. It guards against the
	// "billion laughs" alias-expansion attack.
	ErrAliasBomb = errors.New("yaml: alias expansion exceeds node budget")

	// ErrTypeMismatch indicates a YAML value could not be decoded into the Go
	// value it was assigned to. Decoding collects these into a *TypeError
	// instead of stopping at the first one.
	ErrTypeMismatch = errors.New("yaml: cannot decode value into Go type")

	// ErrUnsupportedType indicates a Go value has no YAML representation, for
	// example a channel or a function.
	ErrUnsupportedType = errors.New("yaml: unsupported type")

	// ErrInvalidUnmarshal indicates Unmarshal or Decode was given something
	// other than a non-nil pointer.
	ErrInvalidUnmarshal = errors.New("yaml: Unmarshal expects a non-nil pointer")

	// ErrClosed indicates Encode was called on an Encoder that has already been
	// closed.
	ErrClosed = errors.New("yaml: encoder is closed")
)

vars.doc:
Sentinel errors returned by the package. Every error produced here wraps at
least one of these, so callers can classify failures with errors.Is:

	if errors.Is(err, yaml.ErrSyntax) { ... }

