consts.signature:
const (
	// DocumentNode is a single document in a stream. It has exactly one child,
	// the document's root node.
	DocumentNode Kind = 1 << iota
	// SequenceNode is a YAML sequence; Content holds its items in order.
	SequenceNode
	// MappingNode is a YAML mapping; Content holds alternating keys and values.
	MappingNode
	// ScalarNode is a YAML scalar; Value holds its (unquoted, unfolded) text.
	ScalarNode
	// AliasNode is an alias (*name); Alias points at the anchored node.
	AliasNode
)

types.signature:
type Marshaler interface {
	// MarshalYAML returns the value that should be encoded in place of the
	// receiver.
	MarshalYAML() (any, error)
}

type Node struct {
	// Kind is what this node is: document, sequence, mapping, scalar or alias.
	Kind Kind

	// Tag is the node's tag, either explicit in the source or resolved by the
	// core schema, in short form (for example "!!str" or "!custom").
	Tag string

	// Value is the scalar's text with quoting removed, escapes decoded and
	// block-scalar folding applied. It is empty for collections.
	Value string

	// Anchor is the anchor name attached to this node ("&name"), without the
	// leading ampersand.
	Anchor string

	// Alias points at the anchored node this alias refers to. It is non-nil
	// only when Kind is AliasNode.
	Alias *Node

	// Content holds a document's single child, a sequence's items, or a
	// mapping's alternating keys and values.
	Content []*Node

	// Style records how the node was written, and how it should be emitted.
	Style Style

	// Line is the 1-based line the node starts on.
	Line int
	// Column is the 1-based column the node starts at.
	Column int

	// HeadComment holds the comment block that precedes the node.
	HeadComment string
	// LineComment holds the comment that trails the node on its own line.
	LineComment string
	// FootComment holds the comment block that follows the node.
	FootComment string
}

consts.signature:
const (
	// TaggedStyle forces the node's tag to be emitted even when the core schema
	// would resolve the value to that tag anyway.
	TaggedStyle Style = 1 << iota
	// DoubleQuotedStyle emits a scalar inside double quotes, with escapes.
	DoubleQuotedStyle
	// SingleQuotedStyle emits a scalar inside single quotes.
	SingleQuotedStyle
	// LiteralStyle emits a scalar as a literal block scalar ("|").
	LiteralStyle
	// FoldedStyle emits a scalar as a folded block scalar (">").
	FoldedStyle
	// FlowStyle emits a collection in flow form ("[a, b]" or "{a: b}").
	FlowStyle
)

types.signature:
type SyntaxError struct {
	// Line is the 1-based line number of the offending construct.
	Line int
	// Column is the 1-based column number of the offending construct.
	Column int
	// Msg describes the problem.
	Msg string
}

type TypeError struct {
	// Errors holds one human-readable message per failure, in the order the
	// failures were encountered.
	Errors []string
}

type Unmarshaler interface {
	// UnmarshalYAML decodes value into the receiver.
	UnmarshalYAML(value *Node) error
}

