package main

import (
	"fmt"
	"time"

	"github.com/malcolmston/yaml"
)

func main() {
	type server struct {
		Host    string        `yaml:"host"`
		Port    int           `yaml:"port"`
		Timeout time.Duration `yaml:"timeout"`
		Debug   bool          `yaml:"debug,omitempty"`
	}
	out, err := yaml.Marshal(server{Host: "localhost", Port: 8080, Timeout: 30 * time.Second})
	if err != nil {
		panic(err)
	}
	fmt.Print(string(out))
}

