import (
	"fmt"

	"github.com/malcolmston/yaml"
)

func main() {
	// Decoding into any resolves scalars with the YAML 1.2 core schema.
	var v any
	if err := yaml.Unmarshal([]byte("a: 1\nb: true\nc: 1.5\nd: ~\ne: text\n"), &v); err != nil {
		panic(err)
	}
	m := v.(map[string]any)
	for _, k := range []string{"a", "b", "c", "d", "e"} {
		fmt.Printf("%s: %T\n", k, m[k])
	}
}

package main

import (
	"fmt"

	"github.com/malcolmston/yaml"
)

func main() {
	// Under the YAML 1.2 core schema only true/false are booleans, so the
	// country code for Norway stays a string. This is the "Norway problem",
	// and a YAML 1.1 parser gets it wrong.
	var v map[string]any
	if err := yaml.Unmarshal([]byte("country: NO\nenabled: true\n"), &v); err != nil {
		panic(err)
	}
	fmt.Printf("%T %v\n", v["country"], v["country"])
	fmt.Printf("%T %v\n", v["enabled"], v["enabled"])
}

package main

import (
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/malcolmston/yaml"
)

func main() {
	stream := strings.NewReader("--- 1\n--- two\n--- [3]\n")
	dec := yaml.NewDecoder(stream)
	for {
		var v any
		err := dec.Decode(&v)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			panic(err)
		}
		fmt.Printf("%#v\n", v)
	}
}

