func main() {
	enc := yaml.NewEncoder(os.Stdout)
	enc.SetIndent(2)
	for _, doc := range []any{
		map[string]any{"first": []any{1, 2}},
		map[string]any{"second": true},
	} {
		if err := enc.Encode(doc); err != nil {
			panic(err)
		}
	}
	if err := enc.Close(); err != nil {
		panic(err)
	}
}

package main

import (
	"fmt"
	"time"

	"github.com/malcolmston/yaml"
)

// duration is a type that chooses its own YAML representation on both sides.
type duration struct{ d time.Duration }

// MarshalYAML implements yaml.Marshaler.
func (v duration) MarshalYAML() (any, error) { return v.d.String(), nil }

// UnmarshalYAML implements yaml.Unmarshaler.
func (v *duration) UnmarshalYAML(n *yaml.Node) error {
	var s string
	if err := n.Decode(&s); err != nil {
		return err
	}
	d, err := time.ParseDuration(s)
	if err != nil {
		return fmt.Errorf("line %d: %w", n.Line, err)
	}
	v.d = d
	return nil
}

func main() {
	out, err := yaml.Marshal(map[string]duration{"ttl": {90 * time.Second}})
	if err != nil {
		panic(err)
	}
	fmt.Print(string(out))
}

