	mapping := docs[0].Content[0]
	key, value := mapping.Content[0], mapping.Content[1]
	fmt.Printf("key %q at line %d, tag %s\n", key.Value, key.Line, key.ShortTag())
	fmt.Printf("value %q, line comment %q\n", value.Value, value.LineComment)
	fmt.Printf("document head comment %q\n", docs[0].HeadComment)
}

