import (
	"errors"
	"fmt"

	"github.com/malcolmston/yaml"
)

func main() {
	// Decoding does not stop at the first bad field: every field that can be
	// stored is stored, and the failures are collected.
	var v struct {
		A int `yaml:"a"`
		B int `yaml:"b"`
		C int `yaml:"c"`
	}
	err := yaml.Unmarshal([]byte("a: 1\nb: nope\nc: also-nope\n"), &v)
	var te *yaml.TypeError
	if errors.As(err, &te) {
		fmt.Printf("%d failures, but a was still stored as %d\n", len(te.Errors), v.A)
	}
}

